const RecoveringAvatar = ({ src, ...props }) => {
  const [hasFailed, setHasFailed] = useState(false);
  const [hasRetried, setHasRetried] = useState(false);
  const [retryKey, setRetryKey] = useState(0);
  const retryTimerRef = useRef(null);

  useEffect(() => {
    window.clearTimeout(retryTimerRef.current);
    setHasFailed(false);
    setHasRetried(false);
    setRetryKey(0);
  }, [src]);

  useEffect(() => {
    const retryAvatar = () => {
      if (document.visibilityState !== "visible") return;
      window.clearTimeout(retryTimerRef.current);
      setHasFailed(false);
      setHasRetried(false);
      setRetryKey((key) => key + 1);
    };

    window.addEventListener("online", retryAvatar);
    document.addEventListener("visibilitychange", retryAvatar);
    return () => {
      window.clearTimeout(retryTimerRef.current);
      window.removeEventListener("online", retryAvatar);
      document.removeEventListener("visibilitychange", retryAvatar);
    };
  }, []);

  const handleError = () => {
    if (!hasRetried) {
      setHasRetried(true);
      retryTimerRef.current = window.setTimeout(
        () => setRetryKey((key) => key + 1),
        1000,
      );
      return;
    }
    setHasFailed(true);
  };

  return (
    <HeaderAvatar
      key={retryKey}
      src={hasFailed ? userDefault : src}
      onError={handleError}
      {...props}
    />
  );
};

