export const Tooltip = ({
  content,
  children,
  placement = "bottom",
  isDarkMode = true,
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const arrowRef = useRef(null);
const { refs, floatingStyles, context } = useFloating({
    open: isOpen,
    onOpenChange: setIsOpen,
    placement,
    strategy: "fixed",
    transform: false, 
    whileElementsMounted: autoUpdate,
    middleware: [
      offset(8),
      flip(),
      shift({ padding: 5 }),
      arrow({ element: arrowRef }),
    ],
  });
  const { isMounted, styles: transitionStyles } = useTransitionStyles(context, {
    duration: 150,
    initial: {
      opacity: 0,
      transform: "scale(0.9)",
    },
    open: {
      opacity: 1,
      transform: "scale(1)",
    },
  });

  const hover = useHover(context, { move: false });
  const focus = useFocus(context);
  const dismiss = useDismiss(context);
  const role = useRole(context, { role: "tooltip" });

  const { getReferenceProps, getFloatingProps } = useInteractions([
    hover,
    focus,
    dismiss,
    role,
  ]);

  if (!content) return children;

  const bgTheme = isDarkMode ? "#111111" : "#ffffff";
  const borderTheme = "#00acb9";

  return (
    <>
      <span
        ref={refs.setReference}
        {...getReferenceProps()}
        style={{ display: "inline-flex" }}
      >
        {children}
      </span>
      {isMounted && (
        <FloatingPortal>
          <TooltipBox
            ref={refs.setFloating}
            $isDarkMode={isDarkMode}
            style={{ ...floatingStyles, ...transitionStyles }}
            {...getFloatingProps()}
          >
            {content}
            <FloatingArrow
              ref={arrowRef}
              context={context}
              fill={bgTheme}
              stroke={borderTheme}
              strokeWidth={1}
            />
          </TooltipBox>
        </FloatingPortal>
      )}
    </>
  );
};
const Header = ({
  sfxVolume = 0.2,
  onOpenLogin,
  onOpenRegister,
  onOpenSettings,
  onOpenVip,
  onOpenShop,
  onOpenHelp,
  onOpenOtherOptions,
  onOpenInfo,
  onOpenAuthorsDirectory,
  isInfoOpen,
  isDarkMode,
  toggleTheme,
  isStickyBgMode,
  setIsStickyBgMode,
  onOpenAchievements,
  currentAvatar,
  onLogout,
  user,
  currentPath,
  setIsFsActive,
  loadingStrategy,
  onSetLoadingStrategy,
}) => {
  const { registerRef } = useTutorial?.() || { registerRef: () => {} };
  const [showUltra, setShowUltra] = useState(false);
  const [showVisualSettings, setShowVisualSettings] = useState(false);
  const [showThemePicker, setShowThemePicker] = useState(false);
  const [accentColor, setAccentColor] = useState(null); // null = без накладення
  const themePickerRef = useRef(null);
  const themePickerBtnRef = useRef(null);
  const avatarSource = user?.photoURL || user?.avatar || currentAvatar || userDefault;
  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);

  // Helper to play sound effects with current volume
  // Оголошено ТУТ — до useEffect-ів, щоб вони могли її викликати
  const playSfx = (sound) => {
    const audio = new Audio(sound);
    audio.volume = sfxVolume;
    audio.play().catch(() => {});
  };

  useEffect(() => {
    if (!isProfileModalOpen) return;

    const handlePointerDown = (event) => {
      const modal = document.getElementById("header-profile-modal");
      const button = document.getElementById("header-profile-button");

      if (
        modal &&
        !modal.contains(event.target) &&
        button &&
        !button.contains(event.target)
      ) {
        setIsProfileModalOpen(false);
      }
    };

    document.addEventListener("mousedown", handlePointerDown);
    return () => document.removeEventListener("mousedown", handlePointerDown);
  }, [isProfileModalOpen]);

  // isSettingsPaused removed — AntiHeaderAd manages its own pause state independently

  // Глобальна комбінація клавіш (Alt + T) для фокусування та навігації по кнопках хедера
  useEffect(() => {
    const handleGlobalKeyDown = (e) => {
      if (
        e.altKey &&
        (e.key.toLowerCase() === "t" || e.key === "е" || e.key === "Е" || e.key === "т" || e.key === "Т")
      ) {
        e.preventDefault();
        playSfx(bell);
        themePickerBtnRef.current?.focus();
      }
    };
    window.addEventListener("keydown", handleGlobalKeyDown);
    return () => window.removeEventListener("keydown", handleGlobalKeyDown);
  }, [sfxVolume]);

  // Фокус на першу кнопку при відкритті модалки
  useEffect(() => {
    if (showThemePicker) {
      const timer = setTimeout(() => {
        const firstBtn = themePickerRef.current?.querySelector("button");
        firstBtn?.focus();
      }, 50);
      return () => clearTimeout(timer);
    }
  }, [showThemePicker]);

  // Управління у відкритій модалці теми (Alt + A переключає акцентні кольори, стрілочки переміщують фокус)
  const handleModalKeyDown = (e) => {
    if (e.key === "Escape") {
      e.preventDefault();
      setShowThemePicker(false);
      themePickerBtnRef.current?.focus();
      return;
    }

    // Alt + A лише всередині відкритої модалки переключає колір акценту
    if (e.altKey && (e.key.toLowerCase() === "a" || e.key === "ф" || e.key === "Ф" || e.key === "а" || e.key === "А")) {
      e.preventDefault();
      playSfx(relax);
      const colors = ACCENT_COLORS.map((c) => c.color);
      const curIdx = colors.indexOf(accentColor);
      const nextIdx = (curIdx + 1) % colors.length;
      setAccentColor(colors[nextIdx]);
      return;
    }

    const focusables = Array.from(
      themePickerRef.current?.querySelectorAll("button") || []
    );
    if (!focusables.length) return;

    const currentIndex = focusables.indexOf(document.activeElement);

    if (e.key === "ArrowRight" || e.key === "ArrowDown") {
      e.preventDefault();
      const nextIndex = currentIndex < focusables.length - 1 ? currentIndex + 1 : 0;
      focusables[nextIndex]?.focus();
    } else if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
      e.preventDefault();
      const prevIndex = currentIndex > 0 ? currentIndex - 1 : focusables.length - 1;
      focusables[prevIndex]?.focus();
    }
  };

  // Переключення між ВСІМА кнопками ХЕДЕРУ за допомогою стрілочок
  const handleHeaderKeyDown = (e) => {
    // Якщо модалка теми відкрита і фокус всередині — модалка має свій обробник
    if (themePickerRef.current && themePickerRef.current.contains(document.activeElement)) {
      return;
    }

    if (["ArrowRight", "ArrowLeft", "ArrowDown", "ArrowUp"].includes(e.key)) {
      const headerContainer = e.currentTarget;
      const buttons = Array.from(
        headerContainer.querySelectorAll("button, [tabindex='0']")
      ).filter((btn) => btn.offsetWidth > 0 && btn.offsetHeight > 0);

      if (!buttons.length) return;

      const currentIndex = buttons.indexOf(document.activeElement);
      if (currentIndex === -1) return;

      if (e.key === "ArrowRight" || e.key === "ArrowDown") {
        e.preventDefault();
        const nextIndex = (currentIndex + 1) % buttons.length;
        buttons[nextIndex]?.focus();
      } else if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
        e.preventDefault();
        const prevIndex = (currentIndex - 1 + buttons.length) % buttons.length;
        buttons[prevIndex]?.focus();
      }
    }
  };

  const {
    visualConfig,
    setVisualConfig,
    resetFilters,
    FILTERS,
    PRESETS,
    customPresets,
    saveCustomPreset,
    deleteCustomPreset,
    updateCustomPresetName,
    reorderCustomPresets,
  } = useVisualFilters(user);

  useEffect(() => {
    const interval = setInterval(() => setShowUltra((prev) => !prev), 3000);
    return () => clearInterval(interval);
  }, []);


  // ==========================================
  //     ОКРЕМІ ОБРОБНИКИ ЗВУКІВ ДЛЯ КНОПОК
  // ==========================================

  // 1. Тема
  const handleThemeToggle = () => {
    playSfx(bell);
    toggleTheme();
  };

  // 2. Фон на увесь сайт
  const handleStickyBgToggle = () => {
    playSfx(conimg);
    setIsStickyBgMode((prev) => !prev);
  };

  // 4. Око (Налаштування вигляду)
  const handleEyeToggle = () => {
    playSfx(relax);
    setShowVisualSettings((prev) => !prev);
  };

  // 5. Допомога / Навчання (?)
  const handleHelpClick = () => {
    playSfx(relax);
    if (onOpenHelp) onOpenHelp();
  };

  // 6. Магазин
  const handleShopClick = () => {
    playSfx(relax);
    if (onOpenShop) onOpenShop();
  };

  // 7. Інші опції (три крапки)
  const handleOtherOptionsClick = () => {
    playSfx(relax);
    if (onOpenOtherOptions) onOpenOtherOptions();
  };

  // 8. Налаштування (шестерня)
  const handleSettingsClick = () => {
    playSfx(relax);
    if (onOpenSettings) onOpenSettings();
  };

  // 9. Вихід з акаунту
  const handleLogoutClick = () => {
    playSfx(relax);
    if (onLogout) onLogout();
  };

  // 10. Кнопка "Вхід" (для незалогіненого)
  const handleLoginClick = () => {
    playSfx(relax);
    if (onOpenLogin) onOpenLogin();
  };

  // 11. Кнопка "Акаунт" / "Реєстрація" (для незалогіненого)
  const handleRegisterClick = () => {
    playSfx(relax);
    if (onOpenRegister) onOpenRegister();
  };

  // 12. Кнопки фільтрів у панелі вигляду
  const handleFilterClick = (filterId) => {
    playSfx(relax);
    setVisualConfig((prev) => ({ ...prev, filterType: filterId }));
  };

  // 13. Пресети стилів
  const handlePresetClick = (config) => {
    playSfx(relax);
    setVisualConfig(config);
  };

  return (
    <><HeaderDiv
  $isDarkMode={isDarkMode}
  $isStickyBgMode={isStickyBgMode}
  $accentColor={accentColor}
  data-decorator-ignore="true"
>
  <HeaderFix>
    {user ? (
      <>
        <ButtonsGroup ref={(el) => registerRef('headerBgTheme', el)} onKeyDown={handleHeaderKeyDown}>
          {/* Тема — відкриває міні-модалку вибору теми */}
          <div style={{ position: "relative", display: "inline-flex" }}>
            <Tooltip content="Вибір теми" isDarkMode={isDarkMode}>
              <IconButton
                ref={themePickerBtnRef}
                onClick={() => { playSfx(bell); setShowThemePicker(p => !p); }}
                onKeyDown={(e) => {
                  if (e.key === "ArrowDown" || e.key === "Enter" || e.key === " ") {
                    if (e.key === "ArrowDown") e.preventDefault();
                    setShowThemePicker(true);
                  }
                }}
                $isDarkMode={isDarkMode}
                aria-label="Вибір теми (Alt + T)"
                style={{ position: "relative" }}
              >
                <EmojiWrapper style={{ fontSize: "19px" }}>
                  <IoColorPalette />
                </EmojiWrapper>
                {/* маленька крапка акценту */}
                {accentColor && (
                  <span style={{
                    position: "absolute",
                    bottom: 1, right: 1,
                    width: 6, height: 6,
                    borderRadius: "50%",
                    background: accentColor,
                    border: "1px solid rgba(0,0,0,0.3)"
                  }} />
                )}
              </IconButton>
            </Tooltip>

            {showThemePicker && (
              <ThemePickerModal
                ref={themePickerRef}
                $isDarkMode={isDarkMode}
                tabIndex={-1}
                onKeyDown={handleModalKeyDown}
              >
                {/* Базова тема */}
                <ThemePickerSection>Базова тема</ThemePickerSection>
                <ThemeBaseRow>
                  <ThemeBaseBtn
                    $bg="#ffffff"
                    $color="#111"
                    $active={!isDarkMode}
                    onClick={() => { if (isDarkMode) { playSfx(bell); toggleTheme(); } }}
                  >
                    ☀️ Світла
                  </ThemeBaseBtn>
                  <ThemeBaseBtn
                    $bg="#111111"
                    $color="#fff"
                    $active={isDarkMode}
                    onClick={() => { if (!isDarkMode) { playSfx(bell); toggleTheme(); } }}
                  >
                    🌙 Темна
                  </ThemeBaseBtn>
                </ThemeBaseRow>

                {/* Акцентний колір */}
                <ThemePickerSection>Акцентний колір</ThemePickerSection>
                <AccentRow>
                  {ACCENT_COLORS.map((ac) => (
                    <Tooltip key={ac.id} content={ac.label} isDarkMode={isDarkMode} placement="top">
                      <AccentDot
                        $color={ac.color || (isDarkMode ? "#555" : "#ccc")}
                        $active={accentColor === ac.color}
                        onClick={() => { playSfx(relax); setAccentColor(ac.color); }}
                        title={ac.label}
                        style={ac.id === "none" ? {
                          background: "linear-gradient(135deg,#ccc 40%,#fff 60%)",
                          border: "2px solid #aaa",
                        } : {}}
                      />
                    </Tooltip>
                  ))}
                </AccentRow>
                {/* Смуга-превью акценту */}
                <AccentPreviewBar $color={accentColor} />
                <div style={{ fontSize: 10, opacity: 0.45, textAlign: "center" }}>
                  {accentColor
                    ? `Акцент: ${ACCENT_COLORS.find(a => a.color === accentColor)?.label}`
                    : "Без накладення кольору"}
                </div>
              </ThemePickerModal>
            )}
          </div>

          {/* Липкий фон */}
          <Tooltip content="Фон на увесь сайт" isDarkMode={isDarkMode}>
            <IconButton
              onClick={handleStickyBgToggle}
              $isDarkMode={isDarkMode}
              aria-label="Фон на увесь сайт"
            >
              <EmojiWrapper>
                <MdWallpaper
                  style={{ color: isStickyBgMode ? "#ff005d" : "inherit" }}
                />
              </EmojiWrapper>
            </IconButton>
          </Tooltip>
          {/* Допомога (?) */}
          <Tooltip content="Допомога з сайтом" isDarkMode={isDarkMode}>
            <IconButton 
              onClick={handleHelpClick} 
              $isDarkMode={isDarkMode}
              aria-label="Допомога з сайтом"
            >
              <EmojiWrapper style={{ fontWeight: 900 }}>?</EmojiWrapper>
            </IconButton>
          </Tooltip>

          {/* Магазин */}
          <Tooltip content="Станьте нашим спосором, та підтримайте інші екологічні компанії!" isDarkMode={isDarkMode}>
            <IconButton
              onClick={handleShopClick}
              $isDarkMode={isDarkMode}
              aria-label="Станьте нашим спосором, та підтримайте інші екологічні компанії!"
            >
              <GiShop />
            </IconButton>
          </Tooltip>

          {/* Автори / джерела */}
          <Tooltip content="Автори та джерела" isDarkMode={isDarkMode}>
            <IconButton
              onClick={() => onOpenAuthorsDirectory?.()}
              $isDarkMode={isDarkMode}
              aria-label="Автори та джерела"
            >
              <EmojiWrapper style={{ fontSize: "18px" }}><FaBookOpen/></EmojiWrapper>
            </IconButton>
          </Tooltip>

          {/* Налаштування */}
          <Tooltip content="Налаштування" isDarkMode={isDarkMode}>
            <IconButton 
              onClick={handleSettingsClick} 
              $isDarkMode={isDarkMode}
              aria-label="Налаштування"
            >
              <EmojiWrapper>
                <MdSettingsSuggest />
              </EmojiWrapper>
            </IconButton>
          </Tooltip>

          {/* Вихід */}
          <Tooltip content="Вихід з акаунта" isDarkMode={isDarkMode}>
            <IconButton 
              onClick={handleLogoutClick} 
              $isDarkMode={isDarkMode}
              aria-label="Вихід з акаунта"
            >
              <EmojiWrapper>
                <GiExitDoor />
              </EmojiWrapper>
            </IconButton>
          </Tooltip>

        <ProfileButtonWrap>
          <Tooltip content="Ваш профіль" isDarkMode={isDarkMode}>
          <ProfileButton
            id="header-profile-button"
            $isDarkMode={isDarkMode}
            onClick={() => setIsProfileModalOpen((prev) => !prev)}
            aria-label="Профіль користувача"
          >
            <RecoveringAvatar
              src={avatarSource}
              $bColor={user.borderColor}
              style={{ width: "33px", height: "33px" }}
            />
          </ProfileButton>
         </Tooltip>
          {isProfileModalOpen && (
            <ProfileModal
              id="header-profile-modal"
              $isDarkMode={isDarkMode}
            >
              <ProfileModalBody>
                <RecoveringAvatar
                  src={avatarSource}
                  $bColor={user.borderColor}
                  style={{ width: "42px", height: "42px" }}
                />
                <div>
                  <ProfileModalLabel>Профіль</ProfileModalLabel>
                   <ProfileModalName>Електронна пошта: {user.email || user.account}</ProfileModalName>
                </div>
              </ProfileModalBody>
            </ProfileModal>
          )}
        </ProfileButtonWrap>
        </ButtonsGroup>
      </>
    ) : (
      <ButtonsGroup ref={(el) => registerRef('headerBgTheme', el)} onKeyDown={handleHeaderKeyDown}>
        {/* Незалогінений користувач */}
        {/* Тема — міні-модалка вибору */}
        <div style={{ position: "relative", display: "inline-flex" }}>
          <Tooltip content="Вибір теми" isDarkMode={isDarkMode}>
            <IconButton
              ref={themePickerBtnRef}
              onClick={() => { playSfx(bell); setShowThemePicker(p => !p); }}
              onKeyDown={(e) => {
                if (e.key === "ArrowDown" || e.key === "Enter" || e.key === " ") {
                  if (e.key === "ArrowDown") e.preventDefault();
                  setShowThemePicker(true);
                }
              }}
              $isDarkMode={isDarkMode}
              aria-label="Вибір теми (Alt + T)"
              style={{ position: "relative" }}
            >
              <EmojiWrapper style={{ fontSize: "18px" }}>
                <IoColorPalette />
              </EmojiWrapper>
              {accentColor && (
                <span style={{
                  position: "absolute", bottom: 1, right: 1,
                  width: 6, height: 6, borderRadius: "50%",
                  background: accentColor, border: "1px solid rgba(0,0,0,0.3)"
                }} />
              )}
            </IconButton>
          </Tooltip>

          {showThemePicker && (
            <ThemePickerModal
              ref={themePickerRef}
              $isDarkMode={isDarkMode}
              tabIndex={-1}
              onKeyDown={handleModalKeyDown}
            >
              <ThemePickerSection>Базова тема</ThemePickerSection>
              <ThemeBaseRow>
                <ThemeBaseBtn $bg="#ffffff" $color="#111" $active={!isDarkMode}
                  onClick={() => { if (isDarkMode) { playSfx(bell); toggleTheme(); } }}>
                  ☀️ Світла
                </ThemeBaseBtn>
                <ThemeBaseBtn $bg="#111111" $color="#fff" $active={isDarkMode}
                  onClick={() => { if (!isDarkMode) { playSfx(bell); toggleTheme(); } }}>
                  🌙 Темна
                </ThemeBaseBtn>
              </ThemeBaseRow>
              <ThemePickerSection>Акцентний колір</ThemePickerSection>
              <AccentRow>
                {ACCENT_COLORS.map((ac) => (
                  <Tooltip key={ac.id} content={ac.label} isDarkMode={isDarkMode} placement="top">
                    <AccentDot
                      $color={ac.color || (isDarkMode ? "#555" : "#ccc")}
                      $active={accentColor === ac.color}
                      onClick={() => { playSfx(relax); setAccentColor(ac.color); }}
                      style={ac.id === "none" ? {
                        background: "linear-gradient(135deg,#ccc 40%,#fff 60%)",
                        border: "2px solid #aaa",
                      } : {}}
                    />
                  </Tooltip>
                ))}
              </AccentRow>
              <AccentPreviewBar $color={accentColor} />
              <div style={{ fontSize: 10, opacity: 0.45, textAlign: "center" }}>
                {accentColor
                  ? `Акцент: ${ACCENT_COLORS.find(a => a.color === accentColor)?.label}`
                  : "Без накладення кольору"}
              </div>
            </ThemePickerModal>
          )}
        </div>

        <Tooltip content="Фон на увесь сайт" isDarkMode={isDarkMode}>
          <IconButton
            onClick={handleStickyBgToggle}
            $isDarkMode={isDarkMode}
            aria-label="Фон на увесь сайт"
          >
            <EmojiWrapper>
              <MdWallpaper
                style={{ color: isStickyBgMode ? "#ff005d" : "inherit" }}
              />
            </EmojiWrapper>
          </IconButton>
        </Tooltip>
        <Tooltip content="Навчання" isDarkMode={isDarkMode}>
          <IconButton
            onClick={handleHelpClick}
            $isDarkMode={isDarkMode}
            aria-label="Навчання"
          >
            <EmojiWrapper style={{ fontWeight: 900 }}>?</EmojiWrapper>
          </IconButton>
        </Tooltip>
        
          {/* Магазин */}
          <Tooltip content="Станьте нашим спосором, та підтримайте інші екологічні компанії!" isDarkMode={isDarkMode}>
            <IconButton
              onClick={handleShopClick}
              $isDarkMode={isDarkMode}
              aria-label="Станьте нашим спосором, та підтримайте інші екологічні компанії!"
            >
              <GiShop />
            </IconButton>
          </Tooltip>

          <Tooltip content="Автори та джерела" isDarkMode={isDarkMode}>
            <IconButton
              onClick={() => onOpenAuthorsDirectory?.()}
              $isDarkMode={isDarkMode}
              aria-label="Автори та джерела"
            >
              <EmojiWrapper style={{ fontSize: "18px" }}><FaBookOpen/></EmojiWrapper>
            </IconButton>
          </Tooltip>

        <button
          onClick={handleLoginClick}
          style={{
            fontSize: "11px",
            cursor: "pointer",
            background: "none",
            border: "none",
            textDecoration: "underline",
            display: "none",
            color: isDarkMode ? "#fff" : "#000",
          }}
        >
          Вхід
        </button>

        <button
          onClick={handleRegisterClick}
          style={{
            fontSize: "14px",
            cursor: "pointer",
            background: "none",
            border: "none",
            marginRight: "15px",
            textDecoration: "underline",
            color: isDarkMode ? "#fff" : "#000",
          }}
        >
          Акаунт
        </button>
      </ButtonsGroup>
    )}
  </HeaderFix>
  {showVisualSettings && (
    <VisualSettingsPanel $isDarkMode={isDarkMode}>
      <div>
        <VisualLabel $isDarkMode={isDarkMode}>
          Яскравість <span>{visualConfig.darkIntensity}%</span>
        </VisualLabel>
        <VisualRange
          type="range"
          min="0"
          max="100"
          value={visualConfig.darkIntensity}
          onChange={(e) =>
            setVisualConfig((prev) => ({
              ...prev,
              darkIntensity: Number(e.target.value),
            }))
          }
          $isDarkMode={isDarkMode}
        />
      </div>

      <FilterGrid>
        {FILTERS.map((f) => (
          <FilterButton
            key={f.id}
            $active={visualConfig.filterType === f.id}
            $isDarkMode={isDarkMode}
            onClick={() => handleFilterClick(f.id)}
          >
            {f.label}
          </FilterButton>
        ))}
      </FilterGrid>

      {visualConfig.filterType !== "none" && (
        <div>
          <VisualLabel $isDarkMode={isDarkMode}>
            Сила ефекту <span>{visualConfig.filterIntensity}%</span>
          </VisualLabel>
          <VisualRange
            type="range"
            min="0"
            max="100"
            value={visualConfig.filterIntensity}
            onChange={(e) =>
              setVisualConfig((prev) => ({
                ...prev,
                filterIntensity: Number(e.target.value),
              }))
            }
            $isDarkMode={isDarkMode}
          />
        </div>
      )}

      <div style={{ marginTop: "5px" }}>
        <VisualLabel
          $isDarkMode={isDarkMode}
          style={{ marginBottom: "8px" }}
        >
          Стилі
        </VisualLabel>
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "1fr 1fr",
            gap: "5px",
          }}
        >
          {PRESETS.map((preset) => (
            <button
              key={preset.id}
              style={{
                background: "transparent",
                border: "1px solid #ffb36c",
                color: isDarkMode ? "#ffb36c" : "#333",
                borderRadius: "6px",
                padding: "5px",
                fontSize: "10px",
                fontWeight: "bold",
                cursor: "pointer",
              }}
              onClick={() => handlePresetClick(preset.config)}
            >
              {preset.label}
            </button>
          ))}
          {customPresets.map((preset) => (
            <button
              key={preset.id}
              style={{
                background: "rgba(255, 179, 108, 0.1)",
                border: "1px solid #7afcff",
                color: isDarkMode ? "#7afcff" : "#006666",
                borderRadius: "6px",
                padding: "5px",
                fontSize: "10px",
                fontWeight: "bold",
                cursor: "pointer",
                overflow: "hidden",
                textOverflow: "ellipsis",
              }}
              onClick={() => handlePresetClick(preset.config)}
            >
              {preset.label}
            </button>
          ))}
        </div>
      </div>
    </VisualSettingsPanel>
  )}
  </HeaderDiv>

   {/* <AntiHeaderAd
    isDarkMode={isDarkMode}
    accentColor={accentColor}
    onOpenShop={handleShopClick}
  /> */}
    </>
  );
};

export default Header;
